function switchTab(tabId) {
  document.querySelectorAll('.tab-btn').forEach(btn => btn.classList.remove('active'));
  document.querySelectorAll('.tab-section').forEach(sec => sec.classList.remove('active'));
  
  const activeBtn = Array.from(document.querySelectorAll('.tab-btn')).find(b => b.getAttribute('onclick')?.includes(tabId));
  if (activeBtn) activeBtn.classList.add('active');
  
  const activeSec = document.getElementById(tabId);
  if (activeSec) activeSec.classList.add('active');
}

function renderSites() {
  const group = document.getElementById('filter-group').value;
  const priority = document.getElementById('filter-priority').value;
  const query = document.getElementById('search-sites').value.toLowerCase().trim();

  const grid = document.getElementById('sites-grid');
  grid.innerHTML = '';

  const filtered = SITES_DATA.filter(site => {
    if (group !== 'ALL' && site.group !== group) return false;
    if (priority !== 'ALL' && site.priority !== priority) return false;
    if (query) {
      const matchText = `${site.domain} ${site.name} ${site.name_zh} ${site.keywords.primary} ${site.target_markets.join(' ')}`.toLowerCase();
      if (!matchText.includes(query)) return false;
    }
    return true;
  });

  filtered.forEach(site => {
    const card = document.createElement('div');
    card.className = 'site-card';
    card.innerHTML = `
      <div>
        <div class="site-card-header">
          <a href="https://${site.domain}" target="_blank" class="site-domain">${site.domain}</a>
          <span class="site-group-badge group-${site.group}">${site.group}组 · ${site.priority}</span>
        </div>
        <div class="site-name-zh">${site.name_zh}</div>
        <div class="site-positioning">${site.positioning}</div>
        <div class="site-meta-list">
          <div>🎯 <strong>Primary Keyword:</strong> \`${site.keywords.primary}\`</div>
          <div>🌍 <strong>Markets:</strong> ${site.target_markets.slice(0, 3).join(', ')}</div>
          <div>📢 <strong>Primary CTA:</strong> "${site.primary_cta}"</div>
        </div>
      </div>
      <div class="site-actions">
        <button class="btn-sm btn-primary-sm" onclick="openStudioForSite('${site.id}')">Generate Content</button>
        <button class="btn-sm" onclick="showSiteDetail('${site.id}')">Strategy Brief</button>
      </div>
    `;
    grid.appendChild(card);
  });
}

function openStudioForSite(siteId) {
  switchTab('studio');
  const select = document.getElementById('studio-site-select');
  select.value = siteId;
  onStudioSiteChange();
  generateStudioContent();
}

function onStudioSiteChange() {
  const siteId = document.getElementById('studio-site-select').value;
  currentSite = SITES_DATA.find(s => s.id === siteId) || SITES_DATA[0];
  
  const skuSelect = document.getElementById('studio-sku-select');
  skuSelect.innerHTML = '';
  
  const relevantProducts = PIM_DATA.filter(p => p.applicable_sites && p.applicable_sites.includes(siteId));
  const listToRender = relevantProducts.length > 0 ? relevantProducts : PIM_DATA;

  listToRender.forEach(p => {
    const opt = document.createElement('option');
    opt.value = p.sku_id;
    opt.textContent = `${p.sku_id} - ${p.name}`;
    skuSelect.appendChild(opt);
  });
  currentProduct = listToRender[0];
}

function onStudioTypeChange() {
  const type = document.getElementById('studio-page-type').value;
  const skuGroup = document.getElementById('sku-select-group');
  if (type === 'product') {
    skuGroup.style.display = 'block';
  } else {
    skuGroup.style.display = 'none';
  }
}

