function setPreviewFormat(fmt) {
  currentFormat = fmt;
  document.querySelectorAll('.format-btn').forEach(b => b.classList.remove('active'));
  const activeBtn = Array.from(document.querySelectorAll('.format-btn')).find(b => b.textContent.toLowerCase().includes(fmt));
  if (activeBtn) activeBtn.classList.add('active');
  updateStudioPreview();
}

function updateStudioPreview() {
  const renderedBox = document.getElementById('preview-box-rendered');
  const codeBox = document.getElementById('preview-box-code');

  if (currentFormat === 'rendered') {
    renderedBox.style.display = 'block';
    codeBox.style.display = 'none';
    renderedBox.innerHTML = currentGeneratedData.html || '';
  } else if (currentFormat === 'markdown') {
    renderedBox.style.display = 'none';
    codeBox.style.display = 'block';
    codeBox.textContent = currentGeneratedData.markdown || '';
  } else if (currentFormat === 'html') {
    renderedBox.style.display = 'none';
    codeBox.style.display = 'block';
    codeBox.textContent = currentGeneratedData.html || '';
  } else if (currentFormat === 'schema') {
    renderedBox.style.display = 'none';
    codeBox.style.display = 'block';
    codeBox.textContent = JSON.stringify(currentGeneratedData.jsonld || {}, null, 2);
  }
}

function copyStudioOutput() {
  let text = '';
  if (currentFormat === 'markdown') text = currentGeneratedData.markdown;
  else if (currentFormat === 'html' || currentFormat === 'rendered') text = currentGeneratedData.html;
  else if (currentFormat === 'schema') text = JSON.stringify(currentGeneratedData.jsonld, null, 2);

  navigator.clipboard.writeText(text).then(() => {
    alert('✅ Copied output to clipboard!');
  }).catch(() => {
    alert('Failed to copy.');
  });
}

function renderRoles() {
  const container = document.getElementById('role-content-container');
  const select = document.getElementById('role-select');
  const roleKey = select ? select.value : 'management';
  const md = ROLES_DATA[roleKey] || 'Role documentation not found.';
  
  // Format basic markdown to HTML
  const html = md
    .replace(/^# (.*$)/gim, '<h2 style="color:#0f172a; margin-top:0;">$1</h2>')
    .replace(/^## (.*$)/gim, '<h3 style="color:#1e293b; border-bottom:1px solid #e2e8f0; padding-bottom:0.4rem; margin-top:1.5rem;">$1</h3>')
    .replace(/^> (.*$)/gim, '<blockquote style="border-left:4px solid #3b82f6; margin:0 0 1rem 0; padding-left:1rem; color:#475569;">$1</blockquote>')
    .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
    .replace(/\*(.*?)\*/g, '<em>$1</em>')
    .replace(/\`([^\`]+)\`/g, '<code style="background:#f1f5f9; padding:0.1rem 0.3rem; border-radius:3px;">$1</code>')
    .replace(/^\s*-\s*(.*$)/gim, '<li style="margin-bottom:0.25rem;">$1</li>')
    .replace(/\n\n/g, '<br><br>');

  container.innerHTML = html;
}

function renderGovernance() {
  const tbody = document.getElementById('modules-table-body');
  tbody.innerHTML = '';
  KB_MODULES.forEach(mod => {
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td style="font-family:monospace; font-weight:600; color:#3b82f6;">${mod.id}</td>
      <td style="font-weight:600; color:#1e293b;">${mod.title}</td>
      <td><span style="background:#ecfdf5; color:#047857; font-size:0.75rem; padding:0.2rem 0.5rem; border-radius:4px; font-weight:700;">${mod.status}</span></td>
      <td style="color:#64748b; font-size:0.85rem;">${mod.outputs}</td>
    `;
    tbody.appendChild(tr);
  });
}

